select event_day, event_type, unique_event_types, product_count from (select to_date(event_time) as event_day, event_type, count(distinct duration_sec) as unique_event_types, count(case when page = '/product' then 1 end) as product_count from web_events where event_type in ('purchase', 'add_to_cart', 'page_view') group by to_date(event_time), event_type) as x where unique_event_types < 3 order by unique_event_types asc
